window.SB_PINE_SRC = "//@version=5\n// Stock Blueprint - CHoCH + FVG (discount): the Backtest Lab's rules drawn on the TradingView chart.\n// Owner, 11-Nov-2026: \"i open trading view chart and i go to that trade date. i check how our backtest enter the trade,\n// how our backtest where it is marked Choch, FVG ... it would be helpful if i got pinescript indicator\".\n// The same rules as the laptop (pcbridge/ScreenerBridge/structure.py, kite_intraday.py, backtest_lab.py):\n//  - swing high / low = a candle above / below the N candles on both sides (known - and drawn - N candles later); or (the\n//    Lab's \"Swings: ZigZag\") the highest high since the last swing low, known when price fell x ATR(14) under it (a low\n//    mirrored); \"A swing must stand out by x ATR\" = a candles-each-side swing x ATR above the lowest low around it\n//  - CHoCH = the first candle that CLOSES above the last swing high (or the PROTECTED high = the swing high right before the\n//    lowest swing low since the last CHoCH) after at least M lower highs AND M lower lows (\"Equal highs / lows\": a high or\n//    low within x ATR of the one before is not lower)\n//  - the move = from the CHoCH's final low (the lowest low between that swing high and the CHoCH candle) to the highest high since\n//  - BOS = after the CHoCH, the first close above the highest swing high confirmed after it; a close under the final low ends the CHoCH\n//  - zones: 3-candle FVG (gap >= 0.70 x the 14-candle average range), Gap-up zones (3 - 5 %, or any size between two big green candles = inside FVG)\n//  - BUY = the FIRST time price comes back to a zone that formed after the final low, on the first pullback (no BOS yet),\n//    with the zone's middle at least 50 % down the move (the discount); one BUY a candle (the first zone price reaches that passes\n//    every rule - also the entry / stop / risk / target rules, like the Lab picks a candle's first row that passes)\n// The Backtest Lab page's \"Copy TradingView script\" button writes the run's rules into the inputs below (owner, 11-Nov-2026:\n// \"give option to copy the pinescript in this page that works with respect to the current setup\").\n// Kept in step with tradingview/pine_model.py - tests/tradingview-pine.test.js checks that model against the laptop's Lab runs.\nindicator(\"Stock Blueprint - CHoCH + FVG\", shorttitle=\"SB CHoCH+FVG\", overlay=true, max_boxes_count=500, max_lines_count=500, max_labels_count=500, max_bars_back=5000)\n\n// ------------------------------------------------------------------ inputs (= the Backtest Lab's defaults)\nG1 = \"Market structure (Backtest Lab step 2)\"\nstructOnly = input.bool(true, \"Only my setup (the market-structure rules below)\", group=G1)\npivN = input.int(5, \"A swing: candles each side\", minval=2, maxval=20, group=G1)\ndownN = input.int(3, \"Lower highs and lower lows before the CHoCH, at least\", minval=1, maxval=8, group=G1)\nzoneWhen = input.string(\"In the CHoCH move or after it\", \"The zone formed\", options=[\"In the CHoCH move or after it\", \"Only in the CHoCH move\", \"Only after the CHoCH candle\"], group=G1)\nchochAge = input.int(0, \"The signal at most N candles after the CHoCH (0 = any)\", minval=0, group=G1)\nfibLvl = input.float(0.5, \"Discount: the zone at least this far down the move (0 = off)\", options=[0.0, 0.382, 0.5, 0.618, 0.705, 0.786], group=G1)\ndiscPart = input.string(\"Middle\", \"... judged on the zone's\", options=[\"Middle\", \"Top\", \"Bottom\"], group=G1)\nfirstPull = input.bool(true, \"First pullback only (no BOS yet)\", group=G1)\nbelowChoch = input.bool(false, \"Zone top below the CHoCH level (strict)\", group=G1)\nzonePick = input.string(\"Trade the 2nd (the 1st only watched)\", \"Two discount zones in the CHoCH move\", options=[\"Trade the 2nd (the 1st only watched)\", \"Trade every zone\"], group=G1)\ntouchAgain = input.bool(true, \"A zone touched before the CHoCH counts again after it\", group=G1)\n// how swings and the CHoCH are found (the Lab's More rules > Market structure; owner, 12-Nov-2026)\nswMode = input.string(\"Candles each side\", \"Swings\", options=[\"Candles each side\", \"ZigZag (ATR)\"], group=G1)\nzzAtr = input.float(2.0, \"ZigZag: a turn of x ATR(14)\", minval=0.5, maxval=10, step=0.5, group=G1)\nswAtr = input.float(0.0, \"A swing must stand out by x ATR(14) (0 = not checked; candles-each-side swings)\", minval=0, maxval=5, step=0.5, group=G1)\nchMode = input.string(\"The last swing high\", \"The CHoCH closes above\", options=[\"The last swing high\", \"The protected high\"], group=G1)\neqAtr = input.float(0.0, \"Equal highs / lows: within x ATR(14) (0 = exact)\", minval=0, maxval=2, step=0.05, group=G1)\nG2 = \"Entry, stop, target (Backtest Lab steps 6 - 7)\"\nentryMode = input.string(\"Order at the zone top\", \"Buy\", options=[\"Order at the zone top\", \"Touch candle's close\"], group=G2)\ngapEntry = input.bool(true, \"An FVG with a Gap-up zone inside it: buy at the Gap-up zone top (the stop under the FVG)\", group=G2)\nstopMode = input.string(\"Under the zone bottom\", \"Stop loss\", options=[\"Under the zone bottom\", \"Under the touch candle's low\", \"Under whichever is lower\", \"% under the entry\", \"Under the CHoCH's final low\"], group=G2)\nstopBuf = input.float(0.5, \"Stop: how far below it (%)\", minval=0, step=0.1, group=G2)\nstopPct = input.float(5.0, \"Stop: % under the entry (with that choice)\", minval=0.1, step=0.5, group=G2)\nmaxRisk = input.float(15.0, \"Skip if the risk is more than % (0 = never)\", minval=0, step=1, group=G2)\nminPrice = input.float(0.0, \"Price at least Rs\", minval=0, step=1, group=G2)\ntargetMode = input.string(\"R multiple\", \"Target\", options=[\"R multiple\", \"The last swing high\"], group=G2)\ntargetR = input.float(2.0, \"Target (R = times the risk)\", minval=0.25, step=0.25, group=G2)\nswingMinR = input.float(1.0, \"Swing-high target: at least this many R above the entry\", minval=0, step=0.25, group=G2)\nG6 = \"Filters (Backtest Lab steps 1 and 4)\"\nuseDates = input.bool(false, \"Only signals between these dates\", group=G6)\nfromDate = input.time(timestamp(\"01 Jan 2020 00:00 +0530\"), \"From\", group=G6)\ntoDate = input.time(timestamp(\"31 Dec 2030 00:00 +0530\"), \"To\", group=G6)\nminTurn = input.float(0.0, \"Daily turnover at least Rs lakh (20-day average, 0 = off)\", minval=0, step=10, group=G6)\nemaSup = input.string(\"Off\", \"The signal candle took support at\", options=[\"Off\", \"10 EMA\", \"21 EMA\", \"50 EMA\", \"Any of 10 / 21 / 50\"], group=G6)\nemaTouch = input.float(1.0, \"... its low within % above the EMA\", minval=0, step=0.25, group=G6)\nab10 = input.bool(false, \"It closed above the 10 EMA\", group=G6)\nab21 = input.bool(false, \"It closed above the 21 EMA\", group=G6)\nab50 = input.bool(false, \"It closed above the 50 EMA\", group=G6)\nemaStack = input.bool(false, \"EMAs in order 10 > 21 > 50\", group=G6)\nG3 = \"Zones\"\nfvgK = input.float(0.70, \"FVG: gap at least x the 14-candle average range\", minval=0, step=0.05, group=G3)\ngapMin = input.float(3.0, \"Gap-up zone: gap at least %\", minval=0, step=0.5, group=G3)\ngapMax = input.float(5.0, \"Gap-up zone: gap at most %\", minval=0, step=0.5, group=G3)\ninsideBody = input.float(2.0, \"Inside FVG: both green candles' body at least % of the open\", minval=0, step=0.5, group=G3)\nG4 = \"Spring (the pattern's own rule)\"\nspBody = input.float(0.5, \"Red candle: body at least % of its open\", minval=0, step=0.1, group=G4)\nspUnder = input.float(0.10, \"Spring low at least % under the red candle's low\", minval=0, step=0.05, group=G4)\nspBodyMax = input.float(30.0, \"Spring body under % of the red candle's body\", minval=1, step=1, group=G4)\nspReclaim = input.float(50.0, \"Spring high at most % of the red candle's range above its low\", minval=1, step=5, group=G4)\nsp1315 = input.bool(true, \"4H chart: Springs only on the 13:15 candle\", group=G4)\nG5 = \"Show\"\nshowSwings = input.bool(true, \"Swing highs / lows\", group=G5)\nshowZones = input.bool(true, \"Zones of the CHoCH move (while price has not come back)\", group=G5)\nshowAll = input.bool(false, \"Every FVG / Gap-up zone\", group=G5)\nshowSpring = input.bool(true, \"Spring candles (S)\", group=G5)\nshowTable = input.bool(true, \"Summary table (the current CHoCH)\", group=G5)\nmarkOn = input.bool(false, \"Mark a trade date\", group=G5)\nmarkDate = input.time(timestamp(\"01 Jan 2026 00:00 +0530\"), \"Trade date (from the Backtest Lab)\", group=G5)\n\nC_CHOCH = #b388ff\nC_FIB = #ffd166\nC_BUY = #00c853\nC_STOP = #ff5252\nC_TGT = #448aff\nC_FVG = #26a69a\nC_GAP = #ab47bc\nC_SW = #ffb74d\nTZ = \"Asia/Kolkata\"\n\n// ------------------------------------------------------------------ helpers\npivotHigh(int n) =>\n    bool ok = bar_index >= 2 * n\n    if ok\n        float x = high[n]\n        for k = 1 to n\n            if not (x > high[n + k] and x >= high[n - k])\n                ok := false\n                break\n    ok\n\npivotLow(int n) =>\n    bool ok = bar_index >= 2 * n\n    if ok\n        float y = low[n]\n        for k = 1 to n\n            if not (y < low[n + k] and y <= low[n - k])\n                ok := false\n                break\n    ok\n\nisLocked(float h, float l) =>\n    l > 0 and (h - l) / l * 100 <= 0.05\n\nbigGreen(float o, float c) =>\n    o > 0 and c > o and (c - o) / o * 100 >= insideBody\n\ntwo(int v) =>\n    (v < 10 ? \"0\" : \"\") + str.tostring(v)\n\nfmtT(int t) =>\n    string s = str.tostring(year(t, TZ)) + \"-\" + two(month(t, TZ)) + \"-\" + two(dayofmonth(t, TZ))\n    timeframe.isintraday ? s + \" \" + two(hour(t, TZ)) + \":\" + two(minute(t, TZ)) : s\n\nfmtP(float v) =>\n    str.tostring(v, format.mintick)\n\n// a new zone (f, Gap-up or FVG, bottom, top) linked with the zones of the last 3 candles (= kite_intraday.link_zones, 12-Nov-2026):\n// a Gap-up zone wholly inside an FVG zone - the FVG \"has one inside\" (its touch waits for the Gap-up zone), the Gap-up zone keeps\n// the widest FVG's bottom (its stop)\nlinkZone(int f, bool g, float b, float t, array<int> zF_, array<bool> zGap_, array<bool> zInner_, array<float> zOutB_, array<int> zOutF_, array<int> rF_, array<bool> rGap_, array<float> rBot_, array<float> rTop_) =>\n    int me = array.size(zF_) - 1\n    int nr = array.size(rF_)\n    if nr > 0\n        for j = 0 to nr - 1\n            int rf = array.get(rF_, j)\n            bool rg = array.get(rGap_, j)\n            if rg != g and math.abs(rf - f) <= 3\n                float rb = array.get(rBot_, j)\n                float rt = array.get(rTop_, j)\n                float ib = g ? b : rb\n                float it = g ? t : rt\n                float ob = g ? rb : b\n                float ot = g ? rt : t\n                if ib >= ob - 0.000000001 and it <= ot + 0.000000001\n                    int target = g ? me : -1\n                    float nb = g ? rb : b\n                    int nf = g ? rf : f\n                    if not g\n                        array.set(zInner_, me, true)\n                    int nz = array.size(zF_)\n                    if nz > 0\n                        for k = 0 to nz - 1\n                            if array.get(zF_, k) == rf and array.get(zGap_, k) == rg\n                                if g\n                                    array.set(zInner_, k, true)\n                                else\n                                    target := k\n                    if target >= 0\n                        float cb = array.get(zOutB_, target)\n                        int cf = array.get(zOutF_, target)\n                        if na(cb) or nb < cb or (nb == cb and nf < cf)\n                            array.set(zOutB_, target, nb)\n                            array.set(zOutF_, target, nf)\n    array.push(rF_, f)\n    array.push(rGap_, g)\n    array.push(rBot_, b)\n    array.push(rTop_, t)\n    true\n\n// the market-structure rules of a zone (candle f, bottom, top) under the current CHoCH - the BUY's own test (the 2nd-zone rule)\nzPass(int f, float zb, float zt, int li, int cb, int bos, float lvl, float hh, float lf, int mhb) =>\n    bool ok = f >= li\n    // the owner's rules of 13-Nov-2026: no zone wholly above the CHoCH level; the zone formed in the swing final low -> move high\n    if zb >= lvl - 0.000000001\n        ok := false\n    if f > mhb\n        ok := false\n    if zoneWhen == \"Only in the CHoCH move\" and f > cb + 1\n        ok := false\n    if zoneWhen == \"Only after the CHoCH candle\" and f <= cb\n        ok := false\n    if firstPull and bos >= 0\n        ok := false\n    if belowChoch and not (zt < lvl)\n        ok := false\n    if fibLvl > 0\n        float part = discPart == \"Top\" ? zt : discPart == \"Bottom\" ? zb : (zb + zt) / 2\n        float dep = hh > lf ? (hh - part) / (hh - lf) : na\n        if na(dep) or dep < fibLvl - 0.000000001\n            ok := false\n    ok\n\n// ------------------------------------------------------------------ every bar\nbool isZz = swMode == \"ZigZag (ATR)\"\nbool isProt = chMode == \"The protected high\"\nstring swTxt = (isZz ? \"ZigZag \" + str.tostring(zzAtr) + \" x ATR\" : str.tostring(pivN) + \" candles each side\" + (swAtr > 0 ? \", standing out \" + str.tostring(swAtr) + \" x ATR\" : \"\")) + (isProt ? \" · protected high\" : \"\") + (eqAtr > 0 ? \" · equal within \" + str.tostring(eqAtr) + \" x ATR\" : \"\")\n// ATR(14) like the laptop: the mean true range of the last 14 candles (of the ones there are at the start)\nfloat trNow = bar_index == 0 ? high - low : math.max(high - low, math.abs(high - close[1]), math.abs(low - close[1]))\nfloat trCum = ta.cum(trNow)\nfloat atrS = (trCum - (bar_index >= 14 ? trCum[14] : 0.0)) / math.min(bar_index + 1, 14)\nfloat loWin = ta.lowest(low, 2 * pivN + 1)\nfloat hiWin = ta.highest(high, 2 * pivN + 1)\nbool phRaw = pivotHigh(pivN)\nbool plRaw = pivotLow(pivN)\n// candles-each-side swings (not with ZigZag); \"stand out by x ATR\": above the lowest low / under the highest high around it\nbool ph = not isZz and phRaw and (swAtr <= 0 or high[pivN] - loWin >= swAtr * atrS[pivN])\nbool pl = not isZz and plRaw and (swAtr <= 0 or hiWin - low[pivN] >= swAtr * atrS[pivN])\n\n// the ATR ZigZag: a swing high = the highest high since the last swing low, known on the first candle whose low is zzAtr x\n// ATR under it (a swing low mirrored); then the other side starts from the lowest low / highest high after it (the latest of equals)\nvar int zzD = 0\nvar int zzHi = 0\nvar float zzHiV = na\nvar int zzLo = 0\nvar float zzLoV = na\nbool zzNewHi = false\nbool zzNewLo = false\nint zzP = -1\nfloat zzV = na\nif isZz\n    if bar_index == 0\n        zzHiV := high\n        zzLoV := low\n    else\n        float zA = zzAtr * atrS\n        if zzD >= 0 and high > zzHiV\n            zzHi := bar_index\n            zzHiV := high\n        if zzD <= 0 and low < zzLoV\n            zzLo := bar_index\n            zzLoV := low\n        if zzD >= 0 and zzHi < bar_index and zzHiV - low >= zA and (zzD == 1 or zzHi >= zzLo)\n            zzNewHi := true\n            zzP := zzHi\n            zzV := zzHiV\n            zzD := -1\n            zzLo := bar_index\n            zzLoV := low\n            int m1 = bar_index - zzP - 1\n            if m1 > 0\n                for off = 1 to m1\n                    if low[off] < zzLoV\n                        zzLo := bar_index - off\n                        zzLoV := low[off]\n        else if zzD <= 0 and zzLo < bar_index and high - zzLoV >= zA and (zzD == -1 or zzLo > zzHi)\n            zzNewLo := true\n            zzP := zzLo\n            zzV := zzLoV\n            zzD := 1\n            zzHi := bar_index\n            zzHiV := high\n            int m2 = bar_index - zzP - 1\n            if m2 > 0\n                for off = 1 to m2\n                    if high[off] > zzHiV\n                        zzHi := bar_index - off\n                        zzHiV := high[off]\n\n// the swing confirmed on this candle (for the structure) and the swing high known now (the swing-high target and the BOS)\nbool swNew = isZz ? (zzNewHi or zzNewLo) : ph != pl\nbool swNewH = isZz ? zzNewHi : ph\nint swNewP = isZz ? zzP : bar_index - pivN\nfloat swNewV = isZz ? zzV : ph ? high[pivN] : low[pivN]\nbool hiNew = isZz ? zzNewHi : ph\nint hiNewP = isZz ? zzP : bar_index - pivN\nfloat hiNewV = isZz ? zzV : high[pivN]\nbool lockNow = isLocked(high, low)\nbool lockPrev = bar_index >= 1 and isLocked(high[1], low[1])\nbool gapAny = bar_index >= 1 and not lockNow and not lockPrev and high[1] > 0 and low > high[1]\nfloat gapPct = gapAny ? (low - high[1]) / high[1] * 100 : na\nfloat avgRange = ta.sma(high - low, 14)\n\n// the swing highs known so far (for the swing-high target): pushed when confirmed\nvar phV = array.new_float()\nif hiNew\n    array.push(phV, hiNewV)\n\n// EMAs like the Lab (seeded with the first close) and its confluence rules on the signal candle\nvar float e10 = na\nvar float e21 = na\nvar float e50 = na\ne10 := na(e10) ? close : e10 + 2.0 / 11.0 * (close - e10)\ne21 := na(e21) ? close : e21 + 2.0 / 22.0 * (close - e21)\ne50 := na(e50) ? close : e50 + 2.0 / 51.0 * (close - e50)\nbool emaAny = emaSup != \"Off\" or ab10 or ab21 or ab50 or emaStack\nbool need50 = emaSup == \"50 EMA\" or emaSup == \"Any of 10 / 21 / 50\" or ab50 or emaStack\nbool need21 = emaSup == \"21 EMA\" or emaSup == \"Any of 10 / 21 / 50\" or ab21 or emaStack\nint emaLen = need50 ? 50 : need21 ? 21 : 10\nfloat tch = 1 + emaTouch / 100\nbool s10 = low <= e10 * tch and close >= e10\nbool s21 = low <= e21 * tch and close >= e21\nbool s50 = low <= e50 * tch and close >= e50\nbool supOk = emaSup == \"Off\" ? true : emaSup == \"10 EMA\" ? s10 : emaSup == \"21 EMA\" ? s21 : emaSup == \"50 EMA\" ? s50 : (s10 or s21 or s50)\nbool emaOk = not emaAny or (bar_index >= emaLen and supOk and (not ab10 or close > e10) and (not ab21 or close > e21) and (not ab50 or close > e50) and (not emaStack or (e10 > e21 and e21 > e50)))\n\n// the 20-day average daily turnover (close x volume) in Rs lakh, like the Lab (daily candles on any chart)\nfloat cvCum = ta.cum(close * volume)\nfloat turnHere = (cvCum - (bar_index >= 20 ? cvCum[20] : 0.0)) / math.min(bar_index + 1, 20) / 100000\nfloat turnDaily = request.security(syminfo.tickerid, \"D\", turnHere)\nfloat turnLakh = timeframe.isdaily ? turnHere : turnDaily\nbool turnOk = minTurn <= 0 or math.round(turnLakh * 10) / 10.0 >= minTurn\nbool dateOk = not useDates or (time >= fromDate and time < toDate + 86400000)\n\n// swings (alternating: a second high before a low keeps the higher one) and the CHoCH state\nvar swP = array.new_int()\nvar swV = array.new_float()\nvar swH = array.new_bool()\nvar swA = array.new_float()\nvar int swBase = 0\nvar int lastUsedHi = -1\nvar int segHi = -1\nvar float segMin = na\nvar int segMinBar = -1\nvar int chB = -1\nvar int chHi = -1\nvar float chLvl = na\nvar int chLi = -1\nvar float chLf = na\nvar int chD = 0\nvar bool chDead = true\nvar int chBos = -1\nvar float chPeak = na\nvar int chPeakBar = -1\nvar float chH = na\nvar int chHBar = -1\nvar int chTime = 0\nvar int chLiTime = 0\nvar line fibLn = na\nvar label fibLb = na\nvar int nBuys = 0\nvar string lastBuy = \"-\"\n// zones not touched yet\nvar zF = array.new_int()\nvar zBot = array.new_float()\nvar zTop = array.new_float()\nvar zGap = array.new_bool()\nvar zIn = array.new_bool()\nvar zInner = array.new_bool()\nvar zOutB = array.new_float()\nvar zOutF = array.new_int()\nvar rF = array.new_int()\nvar rGap = array.new_bool()\nvar rBot = array.new_float()\nvar rTop = array.new_float()\nvar zBox = array.new_box()\nvar hitList = array.new_int()\n// the zones price has touched (the 2nd-zone rule: \"1st FVG can be watched but not to be traded\" - owner, 12-Nov-2026)\nvar tzF = array.new_int()\nvar tzB = array.new_float()\nvar tzT = array.new_float()\nvar tzG = array.new_bool()\nvar tzIn = array.new_bool()\nvar tzInner = array.new_bool()\nvar tzOutB = array.new_float()\nvar tzOutF = array.new_int()\nvar rmList = array.new_int()\nvar abB = array.new_float()\nvar abT = array.new_float()\nvar abF = array.new_int()\n\n// 1. a close under the final low ends the CHoCH (this candle too)\nbool alive = chB >= 0 and not chDead and chB < bar_index\nif alive and close < chLf\n    chDead := true\n    alive := false\n    label.new(bar_index, low, \"CHoCH ended\", yloc=yloc.belowbar, style=label.style_label_up, color=color.new(color.gray, 30), textcolor=color.white, size=size.tiny, tooltip=\"A close under the CHoCH's final low \" + fmtP(chLf) + \" - no more setups from this CHoCH\")\n\n// 1b. the candle before's gap between two big green candles (inside FVG - judged now that this candle closed); added before\n//     the touches so the FVG around it knows it (this candle cannot touch it: its low is over the gap's top). The zones of the\n//     last few candles are kept for the links.\nbool prune = true\nwhile prune\n    if array.size(rF) > 0\n        if array.get(rF, 0) < bar_index - 5\n            array.shift(rF)\n            array.shift(rGap)\n            array.shift(rBot)\n            array.shift(rTop)\n        else\n            prune := false\n    else\n        prune := false\nbool zoneBoxOn = showAll or (showZones and chB >= 0 and not chDead)\nif bar_index >= 3 and gapAny[1] and gapPct[1] <= gapMax\n    if bigGreen(open[2], close[2]) and bigGreen(open[1], close[1]) and low[1] > high[2] and high[3] < high[2] and low > low[1]\n        if gapPct[1] >= gapMin\n            int nz5 = array.size(zF)\n            if nz5 > 0\n                for k = 0 to nz5 - 1\n                    if array.get(zF, k) == bar_index - 1 and array.get(zGap, k)\n                        array.set(zIn, k, true)\n        else\n            array.push(zF, bar_index - 1)\n            array.push(zBot, high[2])\n            array.push(zTop, low[1])\n            array.push(zGap, true)\n            array.push(zIn, true)\n            array.push(zInner, false)\n            array.push(zOutB, na)\n            array.push(zOutF, -1)\n            box nb3 = na\n            if zoneBoxOn and (showAll or bar_index - 1 >= chLi)\n                nb3 := box.new(bar_index - 2, low[1], bar_index, high[2], border_color=color.new(C_GAP, 40), bgcolor=color.new(C_GAP, 88), extend=extend.right)\n            array.push(zBox, nb3)\n            linkZone(bar_index - 1, true, high[2], low[1], zF, zGap, zInner, zOutB, zOutF, rF, rGap, rBot, rTop)\n\n// 2. the zones this candle touches for the first time (low <= zone top; a Gap-up zone never on a circuit-locked candle) -\n//    the first one (highest top, FVG before Gap-up, older first) that passes every rule = the BUY\narray.clear(hitList)\nint best = -1\nfloat bEntry = na\nfloat bStop = na\nfloat bTgt = na\nfloat bDep = na\nstring skipWhy = \"\"\nbool aliveOk = alive and (chochAge == 0 or bar_index - chB <= chochAge)\nbool pick2nd = structOnly and zonePick == \"Trade the 2nd (the 1st only watched)\"\nint nz = array.size(zF)\nif nz > 0\n    for k = 0 to nz - 1\n        if low <= array.get(zTop, k) and (not array.get(zGap, k) or not lockNow)\n            array.push(hitList, k)\nint nh0 = array.size(hitList)\nif nh0 > 0\n    for q = 0 to nh0 - 1\n        int k = array.get(hitList, q)\n        float zt = array.get(zTop, k)\n        bool zg = array.get(zGap, k)\n        int f = array.get(zF, k)\n        float zb = array.get(zBot, k)\n        float part = discPart == \"Top\" ? zt : discPart == \"Bottom\" ? zb : (zb + zt) / 2\n        float dep = aliveOk and chH > chLf ? (chH - part) / (chH - chLf) : na\n        bool ok = true\n        // an FVG with a Gap-up zone inside it: the order waits at the Gap-up zone top (its own touch); a Gap-up zone inside an\n        // FVG: the stop under the FVG's bottom\n        bool waitsInside = gapEntry and not zg and array.get(zInner, k)\n        float zbStop = gapEntry and zg and not na(array.get(zOutB, k)) ? array.get(zOutB, k) : zb\n        if waitsInside\n            ok := false\n        if structOnly and ok\n            ok := aliveOk and f >= chLi\n            if zb >= chLvl - 0.000000001\n                ok := false\n            if f > chHBar\n                ok := false\n            if zoneWhen == \"Only in the CHoCH move\" and f > chB + 1\n                ok := false\n            if zoneWhen == \"Only after the CHoCH candle\" and f <= chB\n                ok := false\n            if firstPull and chBos >= 0\n                ok := false\n            if belowChoch and not (zt < chLvl)\n                ok := false\n            if fibLvl > 0 and (na(dep) or dep < fibLvl - 0.000000001)\n                ok := false\n        if structOnly and ok and pick2nd\n            // the 2nd-zone rule: the discount zones above this one (touched before or now; overlapping ones = one area) and an\n            // untouched one under it - of two the 1st is only watched, a 3rd is not traded\n            array.clear(abB)\n            array.clear(abT)\n            array.clear(abF)\n            int ntz = array.size(tzF)\n            if ntz > 0\n                for j = 0 to ntz - 1\n                    int fj = array.get(tzF, j)\n                    float bj = array.get(tzB, j)\n                    float tj = array.get(tzT, j)\n                    if fj >= chLi and fj < bar_index and bj >= zt - 0.000000001 and zPass(fj, bj, tj, chLi, chB, chBos, chLvl, chH, chLf, chHBar)\n                        array.push(abB, bj)\n                        array.push(abT, tj)\n                        array.push(abF, fj)\n            if nh0 > 0\n                for j = 0 to nh0 - 1\n                    int kj = array.get(hitList, j)\n                    if kj != k\n                        int fj = array.get(zF, kj)\n                        float bj = array.get(zBot, kj)\n                        float tj = array.get(zTop, kj)\n                        if fj >= chLi and fj < bar_index and bj >= zt - 0.000000001 and zPass(fj, bj, tj, chLi, chB, chBos, chLvl, chH, chLf, chHBar)\n                            array.push(abB, bj)\n                            array.push(abT, tj)\n                            array.push(abF, fj)\n            bool lowerZ = false\n            if nz > 0\n                for j = 0 to nz - 1\n                    if j != k and not lowerZ\n                        int fj = array.get(zF, j)\n                        float tj = array.get(zTop, j)\n                        if fj >= chLi and fj < bar_index and tj <= zb + 0.000000001 and zPass(fj, array.get(zBot, j), tj, chLi, chB, chBos, chLvl, chH, chLf, chHBar)\n                            lowerZ := true\n            int areas = 0\n            int nab = array.size(abB)\n            int[] ordA = array.sort_indices(abB, order.ascending)\n            float curT = na\n            float a1T = na\n            int a1F = 0\n            if nab > 0\n                for j = 0 to nab - 1\n                    int x = array.get(ordA, j)\n                    if na(curT) or array.get(abB, x) > curT + 0.000000001\n                        areas += 1\n                        curT := array.get(abT, x)\n                        if areas == 1\n                            a1T := curT\n                            a1F := array.get(abF, x)\n                    else\n                        curT := math.max(curT, array.get(abT, x))\n                        if areas == 1\n                            a1T := curT\n                            a1F := math.min(a1F, array.get(abF, x))\n            // the 1st (watched) zone must not be touched before the move high (owner, 13-Nov-2026, APTUS)\n            int a1n = 0\n            if areas == 1\n                int oA1 = bar_index - chHBar\n                int oB1 = bar_index - a1F - 1\n                if oB1 >= oA1\n                    for o8 = oA1 to oB1\n                        if low[o8] <= a1T + 0.000000001\n                            a1n += 1\n            if areas >= 2\n                skipWhy := \"a 3rd discount zone of the CHoCH move - only the 2nd is traded\"\n                ok := false\n            else if a1n > 0\n                skipWhy := \"the 1st (watched) zone was touched before the move high\"\n                ok := false\n            else if areas == 0 and lowerZ\n                skipWhy := \"the 1st of two discount zones of the CHoCH move - only watched (your rule: the trade is on the 2nd, under it)\"\n                ok := false\n        if structOnly and ok\n            // the owner's rules of 13-Nov-2026: at most 2 candles in the zone and no close under its middle before the move high\n            int oA = bar_index - chHBar\n            int oB = bar_index - f - 1\n            int nT = 0\n            bool deepC = false\n            if oB >= oA\n                for o9 = oA to oB\n                    if low[o9] <= zt + 0.000000001\n                        nT += 1\n                        if close[o9] < (zb + zt) / 2 - 0.000000001\n                            deepC := true\n            if deepC\n                skipWhy := \"a candle closed under the zone's middle before the move high\"\n                ok := false\n            else if nT > 2\n                skipWhy := \"more than 2 candles touched the zone before the move high\"\n                ok := false\n        if ok and not dateOk\n            ok := false\n        if ok and not turnOk\n            skipWhy := \"the daily turnover was under Rs \" + str.tostring(minTurn) + \" lakh\"\n            ok := false\n        if ok and not emaOk\n            skipWhy := \"the EMA rules did not agree\"\n            ok := false\n        if ok\n            bool atTop = entryMode == \"Order at the zone top\"\n            float entry = atTop ? math.min(open, zt) : close\n            string sm = atTop and (stopMode == \"Under the touch candle's low\" or stopMode == \"Under whichever is lower\") ? \"Under the zone bottom\" : stopMode\n            float base = sm == \"Under the touch candle's low\" ? low : sm == \"Under whichever is lower\" ? math.min(low, zbStop) : zbStop\n            float stop = sm == \"% under the entry\" ? entry * (1 - stopPct / 100) : sm == \"Under the CHoCH's final low\" ? chLf * (1 - stopBuf / 100) : base * (1 - stopBuf / 100)\n            float risk = entry - stop\n            float tgt = entry + targetR * risk\n            if sm == \"Under the CHoCH's final low\" and not aliveOk\n                skipWhy := \"no live CHoCH (the stop goes under its final low)\"\n                ok := false\n            else if not (entry > 0 and risk > 0)\n                skipWhy := \"it opened under the stop (a gap)\"\n                ok := false\n            else if maxRisk > 0 and risk / entry * 100 > maxRisk\n                skipWhy := \"the risk was \" + str.tostring(math.round(risk / entry * 1000) / 10.0) + \"% (more than \" + str.tostring(maxRisk) + \"%)\"\n                ok := false\n            else if entry < minPrice\n                skipWhy := \"the price was under Rs \" + str.tostring(minPrice)\n                ok := false\n            else if targetMode == \"The last swing high\"\n                float above = entry + swingMinR * risk\n                float sw = na\n                int np = array.size(phV)\n                if np > 0\n                    for j = np - 1 to 0\n                        if array.get(phV, j) >= above\n                            sw := array.get(phV, j)\n                            break\n                if na(sw)\n                    skipWhy := \"no swing high at least \" + str.tostring(swingMinR) + \"R above the entry\"\n                    ok := false\n                else\n                    tgt := sw\n            if ok\n                bool before = best < 0\n                if not before\n                    float bt = array.get(zTop, best)\n                    bool bg = array.get(zGap, best)\n                    before := zt > bt or (zt == bt and not zg and bg) or (zt == bt and zg == bg and f < array.get(zF, best))\n                if before\n                    best := k\n                    bEntry := entry\n                    bStop := stop\n                    bTgt := tgt\n                    bDep := dep\n\nstring chTxt = structOnly and aliveOk ? \"CHoCH \" + fmtP(chLvl) + \" on \" + fmtT(chTime) + \" (\" + str.tostring(chD) + \" lower highs / lows, final low \" + fmtP(chLf) + \" on \" + fmtT(chLiTime) + \")\\nmove high \" + fmtP(chH) : \"no market-structure rule\"\nif best >= 0\n    float zb = array.get(zBot, best)\n    float zt = array.get(zTop, best)\n    int f = array.get(zF, best)\n    bool isGap = array.get(zGap, best)\n    string kind = isGap ? (array.get(zIn, best) ? \"Gap-up zone (inside FVG)\" : \"Gap-up zone\") : \"FVG\"\n    string tip = chTxt + \"\\n\" + kind + \" \" + fmtP(zb) + \" - \" + fmtP(zt) + (na(bDep) ? \"\" : \", its \" + str.lower(discPart) + \" \" + str.tostring(math.round(bDep * 100)) + \"% down the move\") + (structOnly and fibLvl > 0 and aliveOk ? \" (\" + str.tostring(fibLvl * 100) + \"% line \" + fmtP(chH - fibLvl * (chH - chLf)) + \")\" : \"\")\n    nBuys += 1\n    lastBuy := fmtT(time) + \" at \" + fmtP(bEntry)\n    tip := tip + \"\\nentry \" + fmtP(bEntry) + \" · stop \" + fmtP(bStop) + \" · target \" + fmtP(bTgt) + (targetMode == \"R multiple\" ? \" (\" + str.tostring(targetR) + \"R)\" : \" (the last swing high)\") + \" · risk \" + str.tostring(math.round((bEntry - bStop) / bEntry * 1000) / 10.0) + \"%\"\n    label.new(bar_index, low, \"BUY \" + fmtP(bEntry), yloc=yloc.belowbar, style=label.style_label_up, color=C_BUY, textcolor=color.white, size=size.small, tooltip=tip)\n    line.new(bar_index, bEntry, bar_index + 8, bEntry, color=C_BUY, width=2)\n    line.new(bar_index, bStop, bar_index + 8, bStop, color=C_STOP, width=2)\n    line.new(bar_index, bTgt, bar_index + 8, bTgt, color=C_TGT, width=2, style=line.style_dashed)\n    box bxb = array.get(zBox, best)\n    if na(bxb)\n        box.new(isGap ? f - 1 : f - 2, zt, bar_index, zb, border_color=C_BUY, bgcolor=color.new(C_BUY, 80), text=(structOnly and fibLvl > 0 ? \"discount \" : \"\") + kind, text_size=size.tiny, text_color=C_BUY, text_halign=text.align_left, text_valign=text.align_top)\n    else\n        box.set_bgcolor(bxb, color.new(C_BUY, 80))\n        box.set_border_color(bxb, C_BUY)\n        box.set_text(bxb, (structOnly and fibLvl > 0 ? \"discount \" : \"\") + kind)\n        box.set_text_color(bxb, C_BUY)\n        box.set_text_size(bxb, size.tiny)\nelse if skipWhy != \"\"\n    label.new(bar_index, low, \"skip\", yloc=yloc.belowbar, style=label.style_label_up, color=color.new(color.gray, 20), textcolor=color.white, size=size.tiny, tooltip=\"A zone's first touch passed the market-structure rules, but the Lab would skip it: \" + skipWhy + \"\\n\" + chTxt)\n\n// touched zones leave the list (their box stops at this candle; grey = touched, not a setup)\nint nh = array.size(hitList)\nif nh > 0\n    for j = nh - 1 to 0\n        int k = array.get(hitList, j)\n        array.push(tzF, array.get(zF, k))\n        array.push(tzB, array.get(zBot, k))\n        array.push(tzT, array.get(zTop, k))\n        array.push(tzG, array.get(zGap, k))\n        array.push(tzIn, array.get(zIn, k))\n        array.push(tzInner, array.get(zInner, k))\n        array.push(tzOutB, array.get(zOutB, k))\n        array.push(tzOutF, array.get(zOutF, k))\n        box bx = array.get(zBox, k)\n        if not na(bx)\n            box.set_right(bx, bar_index)\n            box.set_extend(bx, extend.none)\n            if k != best\n                box.set_bgcolor(bx, color.new(color.gray, 88))\n                box.set_border_color(bx, color.new(color.gray, 55))\n        array.remove(zF, k)\n        array.remove(zBot, k)\n        array.remove(zTop, k)\n        array.remove(zGap, k)\n        array.remove(zIn, k)\n        array.remove(zInner, k)\n        array.remove(zOutB, k)\n        array.remove(zOutF, k)\n        array.remove(zBox, k)\n// the touched zones kept for the 2nd-zone rule / touchAgain: the newest 300 (= pine_model ZONES_KEPT)\nwhile array.size(tzF) > 300\n    array.shift(tzF)\n    array.shift(tzB)\n    array.shift(tzT)\n    array.shift(tzG)\n    array.shift(tzIn)\n    array.shift(tzInner)\n    array.shift(tzOutB)\n    array.shift(tzOutF)\n\n// 3. BOS: a swing high confirmed now (after the CHoCH candle) raises the peak; a close above the peak = BOS\nif chB >= 0 and not chDead and chBos < 0 and bar_index > chB\n    if hiNew and hiNewP > chB and (na(chPeak) or hiNewV > chPeak)\n        chPeak := hiNewV\n        chPeakBar := hiNewP\n    if not na(chPeak) and close > chPeak\n        chBos := bar_index\n        line.new(chPeakBar, chPeak, bar_index, chPeak, color=C_STOP, width=1)\n        label.new(bar_index, chPeak, \"BOS\", style=label.style_label_down, color=color.new(C_STOP, 10), textcolor=color.white, size=size.tiny, tooltip=\"Break of structure: a close above the highest swing high \" + fmtP(chPeak) + \" since the CHoCH - price already moved; later touches are not the first pullback\")\n\n// 4. the move's high (the next candles' discount line)\nif chB >= 0 and not chDead and bar_index > chB\n    if high > chH\n        chH := high\n        chHBar := bar_index\nif chB >= 0 and not chDead and fibLvl > 0 and not na(fibLn)\n    float fpx = chH - fibLvl * (chH - chLf)\n    line.set_y1(fibLn, fpx)\n    line.set_xy2(fibLn, bar_index, fpx)\n    label.set_xy(fibLb, bar_index, fpx)\n    label.set_text(fibLb, str.tostring(fibLvl * 100) + \"% \" + fmtP(fpx))\n\n// 5. new zones: a 3-candle FVG on this candle, a Gap-up zone 3 - 5 % on this candle (the inside-FVG gap: 1b)\nif bar_index >= 13 and low > high[2] and (low - high[2]) >= fvgK * avgRange\n    array.push(zF, bar_index)\n    array.push(zBot, high[2])\n    array.push(zTop, low)\n    array.push(zGap, false)\n    array.push(zIn, false)\n    array.push(zInner, false)\n    array.push(zOutB, na)\n    array.push(zOutF, -1)\n    box nb1 = na\n    if zoneBoxOn and (showAll or bar_index >= chLi)\n        nb1 := box.new(bar_index - 2, low, bar_index, high[2], border_color=color.new(C_FVG, 40), bgcolor=color.new(C_FVG, 88), extend=extend.right)\n    array.push(zBox, nb1)\n    linkZone(bar_index, false, high[2], low, zF, zGap, zInner, zOutB, zOutF, rF, rGap, rBot, rTop)\nif gapAny and gapPct >= gapMin and gapPct <= gapMax\n    array.push(zF, bar_index)\n    array.push(zBot, high[1])\n    array.push(zTop, low)\n    array.push(zGap, true)\n    array.push(zIn, false)\n    array.push(zInner, false)\n    array.push(zOutB, na)\n    array.push(zOutF, -1)\n    box nb2 = na\n    if zoneBoxOn and (showAll or bar_index >= chLi)\n        nb2 := box.new(bar_index - 1, low, bar_index, high[1], border_color=color.new(C_GAP, 40), bgcolor=color.new(C_GAP, 88), extend=extend.right)\n    array.push(zBox, nb2)\n    linkZone(bar_index, true, high[1], low, zF, zGap, zInner, zOutB, zOutF, rF, rGap, rBot, rTop)\n// the oldest untouched zones go (they formed long before any CHoCH that could use them)\nif array.size(zF) > 300\n    box old = array.shift(zBox)\n    if not na(old)\n        box.delete(old)\n    array.shift(zF)\n    array.shift(zBot)\n    array.shift(zTop)\n    array.shift(zGap)\n    array.shift(zIn)\n    array.shift(zInner)\n    array.shift(zOutB)\n    array.shift(zOutF)\n\n// 6. swings (confirmed later, alternating: a second high before a low keeps the higher one) and the CHoCH (a close above the\n//    last swing high - or the protected high)\nif swNew\n    float swAt = atrS[bar_index - swNewP]\n    int sz = array.size(swP)\n    bool same = false\n    if sz > 0\n        same := array.get(swH, sz - 1) == swNewH\n    if same\n        float lastV = array.get(swV, sz - 1)\n        if (swNewH and swNewV > lastV) or (not swNewH and swNewV < lastV)\n            array.set(swP, sz - 1, swNewP)\n            array.set(swV, sz - 1, swNewV)\n            array.set(swA, sz - 1, swAt)\n    else\n        array.push(swP, swNewP)\n        array.push(swV, swNewV)\n        array.push(swH, swNewH)\n        array.push(swA, swAt)\nint sz6 = array.size(swP)\nif sz6 > 0\n    int q = -1\n    if isProt\n        // the protected high: the swing high right before the lowest swing low since the last CHoCH (the latest of equal lows)\n        int kMin = -1\n        float vMin = na\n        if sz6 > swBase\n            for k = swBase to sz6 - 1\n                if not array.get(swH, k)\n                    float vk = array.get(swV, k)\n                    if kMin < 0 or vk <= vMin\n                        kMin := k\n                        vMin := vk\n        q := kMin >= 0 ? kMin - 1 : -1\n    else\n        q := array.get(swH, sz6 - 1) ? sz6 - 1 : sz6 - 2\n    if q >= 0\n        int hiBar = array.get(swP, q)\n        float lvl = array.get(swV, q)\n        if hiBar != segHi\n            segHi := hiBar\n            segMin := na\n            segMinBar := -1\n            int span = bar_index - hiBar\n            if span > 0\n                for k = 1 to span\n                    int off = span - k\n                    if na(segMin) or low[off] < segMin\n                        segMin := low[off]\n                        segMinBar := bar_index - off\n        else if low < segMin\n            segMin := low\n            segMinBar := bar_index\n        if close > lvl and hiBar > lastUsedHi\n            lastUsedHi := hiBar\n            int dh = 0\n            int kk = q\n            bool more = true\n            while more\n                if kk - 2 >= 0\n                    if array.get(swV, kk) < array.get(swV, kk - 2) - eqAtr * array.get(swA, kk)\n                        dh += 1\n                        kk -= 2\n                    else\n                        more := false\n                else\n                    more := false\n            int dl = 0\n            float prevLow = segMin\n            kk := q - 1\n            more := true\n            while more\n                if kk >= 0\n                    if prevLow < array.get(swV, kk) - eqAtr * array.get(swA, kk)\n                        dl += 1\n                        prevLow := array.get(swV, kk)\n                        kk -= 2\n                    else\n                        more := false\n                else\n                    more := false\n            int d = math.min(dh, dl)\n            if d >= 1 and isProt\n                swBase := sz6\n            if d >= downN\n                chB := bar_index\n                chHi := hiBar\n                chLvl := lvl\n                chLi := segMinBar\n                chLf := segMin\n                chD := d\n                chDead := false\n                chBos := -1\n                chPeak := na\n                chPeakBar := -1\n                chTime := time\n                chLiTime := time[bar_index - segMinBar]\n                float mh = na\n                int mhb = bar_index\n                int span2 = bar_index - chLi\n                for k = 0 to span2\n                    if na(mh) or high[k] >= mh\n                        mh := high[k]\n                        mhb := bar_index - k\n                chH := mh\n                chHBar := mhb\n                line.new(chHi, chLvl, bar_index, chLvl, color=C_CHOCH, width=2, style=line.style_dashed)\n                label.new(bar_index, chLvl, \"CHoCH (\" + str.tostring(d) + \")\", style=label.style_label_down, color=color.new(C_CHOCH, 10), textcolor=color.white, size=size.small, tooltip=\"CHoCH \" + fmtP(chLvl) + \" on \" + fmtT(time) + \": a close above \" + (isProt ? \"the protected high (the swing high before the lowest low)\" : \"the last swing high\") + \" after \" + str.tostring(d) + \" lower highs and lower lows\" + (eqAtr > 0 ? \" (within \" + str.tostring(eqAtr) + \" x ATR = equal, not lower)\" : \"\") + \". Final low \" + fmtP(chLf) + \" on \" + fmtT(chLiTime) + \". Swings: \" + swTxt)\n                label.new(chLi, chLf, \"final low\", yloc=yloc.price, style=label.style_label_up, color=color.new(C_CHOCH, 40), textcolor=color.white, size=size.tiny)\n                if fibLvl > 0\n                    float fp0 = chH - fibLvl * (chH - chLf)\n                    fibLn := line.new(chLi, fp0, bar_index, fp0, color=C_FIB, width=1, style=line.style_dotted)\n                    fibLb := label.new(bar_index, fp0, str.tostring(fibLvl * 100) + \"% \" + fmtP(fp0), style=label.style_label_left, color=color.new(C_FIB, 100), textcolor=C_FIB, size=size.tiny)\n                // a zone of this move price touched before now that held (no close under its bottom) waits again - its first\n                // touch after the CHoCH counts (owner, 13-Nov-2026, SWIGGY)\n                if structOnly and touchAgain\n                    array.clear(rmList)\n                    int ntz6 = array.size(tzF)\n                    if ntz6 > 0\n                        for q6 = 0 to ntz6 - 1\n                            int f6 = array.get(tzF, q6)\n                            float b6 = array.get(tzB, q6)\n                            if f6 >= chLi\n                                bool held6 = true\n                                int back6 = bar_index - f6 - 1\n                                if back6 >= 0\n                                    for j6 = 0 to back6\n                                        if close[j6] < b6\n                                            held6 := false\n                                            break\n                                if held6\n                                    array.push(zF, f6)\n                                    array.push(zBot, b6)\n                                    array.push(zTop, array.get(tzT, q6))\n                                    array.push(zGap, array.get(tzG, q6))\n                                    array.push(zIn, array.get(tzIn, q6))\n                                    array.push(zInner, array.get(tzInner, q6))\n                                    array.push(zOutB, array.get(tzOutB, q6))\n                                    array.push(zOutF, array.get(tzOutF, q6))\n                                    array.push(zBox, na)\n                                    array.push(rmList, q6)\n                    int nrm6 = array.size(rmList)\n                    if nrm6 > 0\n                        for q7 = nrm6 - 1 to 0\n                            int x7 = array.get(rmList, q7)\n                            array.remove(tzF, x7)\n                            array.remove(tzB, x7)\n                            array.remove(tzT, x7)\n                            array.remove(tzG, x7)\n                            array.remove(tzIn, x7)\n                            array.remove(tzInner, x7)\n                            array.remove(tzOutB, x7)\n                            array.remove(tzOutF, x7)\n                // the zones of this move that wait for price (formed after the final low, not touched yet)\n                if showZones and not showAll\n                    int nz6 = array.size(zF)\n                    if nz6 > 0\n                        for k = 0 to nz6 - 1\n                            int ff = array.get(zF, k)\n                            if ff >= chLi and na(array.get(zBox, k))\n                                bool g6 = array.get(zGap, k)\n                                array.set(zBox, k, box.new(g6 ? ff - 1 : ff - 2, array.get(zTop, k), bar_index, array.get(zBot, k), border_color=color.new(g6 ? C_GAP : C_FVG, 40), bgcolor=color.new(g6 ? C_GAP : C_FVG, 88), extend=extend.right))\n\n// ------------------------------------------------------------------ marks\nfloat c1Body = math.abs(close[1] - open[1])\nbool spring = bar_index >= 3 and close[1] < open[1] and c1Body / open[1] >= spBody / 100 and low < low[1] and close > low[1] and math.abs(close - open) < spBodyMax / 100 * c1Body and low <= low[1] * (1 - spUnder / 100) and high <= low[1] + spReclaim / 100 * (high[1] - low[1])\nbool slotOk = not sp1315 or timeframe.period != \"240\" or (hour(time, TZ) == 13 and minute(time, TZ) == 15)\nplotshape(showSpring and spring and slotOk, \"Spring\", shape.triangleup, location.belowbar, color.new(#26c6da, 0), size=size.tiny, text=\"S\", textcolor=color.new(#26c6da, 0))\nplotshape(showSwings and ph, \"Swing high\", shape.circle, location.abovebar, color.new(C_SW, 0), offset=-pivN, size=size.tiny)\nplotshape(showSwings and pl, \"Swing low\", shape.circle, location.belowbar, color.new(C_SW, 0), offset=-pivN, size=size.tiny)\n// ZigZag swings: one line through them (its corners = the swings), redrawn on the last candle\nvar zzPts = array.new<chart.point>()\nvar polyline zzLine = na\nif isZz and showSwings and swNew\n    array.push(zzPts, chart.point.from_index(swNewP, swNewV))\n    if array.size(zzPts) > 9000\n        array.shift(zzPts)\nif isZz and showSwings and barstate.islast and array.size(zzPts) > 1\n    if not na(zzLine)\n        polyline.delete(zzLine)\n    zzLine := polyline.new(zzPts, line_color=color.new(C_SW, 10), line_width=1)\nbool marked = markOn and year(time, TZ) == year(markDate, TZ) and month(time, TZ) == month(markDate, TZ) and dayofmonth(time, TZ) == dayofmonth(markDate, TZ)\nbgcolor(marked ? color.new(#ffd600, 75) : na, title=\"Trade date\")\n\nvar table tb = table.new(position.top_right, 2, 8, bgcolor=color.new(#0f172a, 15), border_color=color.new(#334155, 0), border_width=1, frame_color=color.new(#334155, 0), frame_width=1)\nif showTable and barstate.islast\n    string stTxt = chB < 0 ? \"no CHoCH yet\" : chDead ? \"ended (a close under the final low)\" : chBos >= 0 ? \"after a BOS - no first-pullback BUY now\" : \"alive - waiting for price to come back to a discount zone\"\n    table.cell(tb, 0, 0, \"Stock Blueprint\", text_color=C_FIB, text_size=size.small)\n    table.cell(tb, 1, 0, \"CHoCH + FVG (\" + (isZz ? \"ZigZag\" : str.tostring(pivN)) + \" / \" + str.tostring(downN) + \")\", text_color=color.white, text_size=size.small)\n    table.cell(tb, 0, 1, \"CHoCH\", text_color=color.silver, text_size=size.small)\n    table.cell(tb, 1, 1, chB < 0 ? \"-\" : fmtP(chLvl) + \" on \" + fmtT(chTime) + \" (\" + str.tostring(chD) + \" lower highs / lows)\", text_color=color.white, text_size=size.small)\n    table.cell(tb, 0, 2, \"Final low\", text_color=color.silver, text_size=size.small)\n    table.cell(tb, 1, 2, chB < 0 ? \"-\" : fmtP(chLf) + \" on \" + fmtT(chLiTime), text_color=color.white, text_size=size.small)\n    table.cell(tb, 0, 3, \"Move high\", text_color=color.silver, text_size=size.small)\n    table.cell(tb, 1, 3, chB < 0 ? \"-\" : fmtP(chH), text_color=color.white, text_size=size.small)\n    table.cell(tb, 0, 4, str.tostring(fibLvl * 100) + \"% line\", text_color=color.silver, text_size=size.small)\n    table.cell(tb, 1, 4, chB < 0 or fibLvl <= 0 ? \"-\" : fmtP(chH - fibLvl * (chH - chLf)), text_color=C_FIB, text_size=size.small)\n    table.cell(tb, 0, 5, \"Status\", text_color=color.silver, text_size=size.small)\n    table.cell(tb, 1, 5, stTxt, text_color=color.white, text_size=size.small)\n    table.cell(tb, 0, 6, \"BUY signals\", text_color=color.silver, text_size=size.small)\n    table.cell(tb, 1, 6, str.tostring(nBuys) + \" on this chart · last \" + lastBuy, text_color=C_BUY, text_size=size.small)\n    table.cell(tb, 0, 7, \"Swings\", text_color=color.silver, text_size=size.small)\n    table.cell(tb, 1, 7, swTxt, text_color=color.white, text_size=size.small)\n";
